import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.DrDMl0tG.js";const s="/assets/rayrai_depth_camera.BxCBEEF5.png",u=JSON.parse('{"title":"Rayrai Example: Depth Camera","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_depth_camera.md","filePath":"sections/examples/rayrai/rayrai_depth_camera.md"}'),o={name:"sections/examples/rayrai/rayrai_depth_camera.md"};function d(n,e,l,h,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rayrai-example-depth-camera" tabindex="-1">Rayrai Example: Depth Camera <a class="header-anchor" href="#rayrai-example-depth-camera" aria-label="Permalink to &quot;Rayrai Example: Depth Camera&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Renders a linear depth texture from the Go1 depth camera and shows it in ImGui with a frustum overlay. The sensed points are projected back into the world and drawn as small instanced cubes. This is the recommended RGB/depth sensor path when rayrai is available. The active code path reads rendered depth from rayrai. The source also keeps a disabled (<code>#if 0</code>) <code>World::captureDepthCamera</code> block as a deterministic CPU fallback for headless ray-query use.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p><img src="'+s+'" alt="rayrai_depth_camera example"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_depth_camera</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_depth_camera</span></span></code></pre></div><p>On Windows, run <code>rayrai_depth_camera.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads Go1 with the D455 module and fetches the depth sensor.</li><li>Renders a linear depth texture and shows it in an ImGui window.</li><li>Reads the rayrai depth buffer with <code>raisin::Camera::getRawImage</code>, flipped so rows run top to bottom like the sensor&#39;s own pixel layout.</li><li>Projects the depth image into world-frame points with <code>DepthCamera::depthToPointCloud</code> and draws every fourth pixel in each direction as a small cube in one <code>InstancedVisuals</code> batch, shaded from yellow (near) to blue (far). Pixels without a hit (depth 0) are skipped. The batch is not detectable, so the depth camera never sees its own points.</li><li>Keeps a disabled CPU <code>World::captureDepthCamera</code> fallback that returns depth, a segmentation object id and an optional hit point per pixel, a timestamp, and deterministic depth noise when rayrai rendering is not available.</li><li>Places a sphere and a box in front of the camera using its pose.</li></ul>',13)])])}const _=a(o,[["render",d]]);export{u as __pageData,_ as default};
